update article_info
set like_count = GREATEST(0, COALESCE(like_count,0) + #{count})
where article_id = #{articleId}

update article_info
set collect_count = GREATEST(0, COALESCE(collect_count,0) + #{count})
where article_id = #{articleId}

update article_info
set view_count = view_count + #{count}
where article_id = #{articleId}

update article_info
set comment_count = comment_count + #{count}
where article_id = #{articleId}

update article_info
set share_count = share_count + #{count}
where article_id = #{articleId}

mapper.select:
SELECT a.*, u.nick_name author_name, u.avatar author_avatar FROM article_info a LEFT JOIN user_info u ON a.user_id = u.user_id WHERE a.article_id IN
#{item}
AND a.status = 1 AND a.deleted = 0

SELECT a.article_id AS articleId, a.title, a.cover_image AS coverImage, a.summary, a.view_count AS viewCount, a.like_count AS likeCount, a.collect_count AS collectCount, a.publish_time AS publishTime, u.nick_name AS authorName, u.avatar AS authorAvatar FROM article_info a JOIN article_tag_relation atr ON a.article_id = atr.article_id JOIN user_info u ON a.user_id = u.user_id WHERE a.status = 1 AND a.deleted = 0 AND atr.tag_id IN
#{item}
AND a.article_id NOT IN( SELECT article_id FROM user_action WHERE user_id = #{userId} AND action_type = 7 ) GROUP BY a.article_id ORDER BY (COUNT(DISTINCT atr.tag_id) * 3 + (LN(1 + COALESCE(a.like_count,0)) * 2 + LN(1 + COALESCE(a.collect_count,0)) * 3 + LN(1 + COALESCE(a.view_count,0)) * 0.7) / POW(1 + GREATEST(TIMESTAMPDIFF(HOUR,a.publish_time,NOW()),0) / 72.0, 0.6)) DESC, a.publish_time DESC, a.article_id DESC LIMIT #{limit}

SELECT a.article_id AS articleId, a.title, a.cover_image AS coverImage, a.summary, a.view_count AS viewCount, a.like_count AS likeCount, a.collect_count AS collectCount, a.publish_time AS publishTime, u.nick_name AS authorName, u.avatar AS authorAvatar FROM article_info a JOIN user_info u ON a.user_id = u.user_id WHERE a.status = 1 AND a.deleted = 0
AND a.article_id NOT IN
#{item}
ORDER BY (a.like_count * 2 + a.collect_count * 3 + a.view_count) DESC LIMIT #{limit}
